			resolve = res;
			reject = rej;
		});
		player.playPromises.push({ resolve, reject });
		return promise;
	};
	player.pause = () => {
		player.pauseCalls += 1;
		player.paused = true;
		if (player.src) player.activeSources.delete(player.src);
	};
	player.removeAttribute = (name) => {
		if (name === "src") player.src = "";
	};
	player.load = () => {
		player.loadCalls += 1;
	};
